<?php

declare(strict_types=1);require_once __DIR__.'/../includes/layout.php';$me=require_admin();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$action=(string)($_POST['action']??'save');$id=(int)($_POST['id']??0);if($action==='toggle'){if($id===(int)$me['id'])throw new RuntimeException('ไม่สามารถปิดบัญชีตัวเอง');db()->prepare('UPDATE users SET is_active=1-is_active WHERE id=?')->execute([$id]);}else{$name=trim((string)($_POST['name']??''));$email=trim((string)($_POST['email']??''));$password=(string)($_POST['password']??'');$role=in_array($_POST['role']??'', ['admin','editor'],true)?$_POST['role']:'editor';if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('ข้อมูลผู้ใช้ไม่ถูกต้อง');if($id){$params=[$name,$email,$role];$sql='UPDATE users SET name=?,email=?,role=?,updated_at=NOW()';if($password!==''){$sql.=',password_hash=?';$params[]=password_hash($password,PASSWORD_DEFAULT);}$sql.=' WHERE id=?';$params[]=$id;db()->prepare($sql)->execute($params);}else{if(strlen($password)<8)throw new RuntimeException('รหัสผ่านอย่างน้อย 8 ตัวอักษร');db()->prepare('INSERT INTO users(name,email,password_hash,role,is_active,created_at,updated_at) VALUES(?,?,?,?,1,NOW(),NOW())')->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$role]);}}audit('manage_user',(string)$id);flash('success','บันทึกผู้ใช้งานแล้ว');redirect('admin/users.php');}catch(Throwable $e){$error=$e->getMessage();}}$edit=null;$editId=filter_input(INPUT_GET,'edit',FILTER_VALIDATE_INT);if($editId){$s=db()->prepare('SELECT * FROM users WHERE id=?');$s->execute([$editId]);$edit=$s->fetch()?:null;}$users=db()->query('SELECT * FROM users ORDER BY id')->fetchAll();page_header('ผู้ใช้งาน',true);require __DIR__.'/_nav.php';?><h1>ผู้ใช้งานหลังบ้าน</h1><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif?><div class="form-card"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><div class="field"><label>ชื่อ</label><input name="name" value="<?=e($edit['name']??'')?>" required></div><div class="field"><label>อีเมล</label><input type="email" name="email" value="<?=e($edit['email']??'')?>" required></div><div class="field"><label>รหัสผ่าน <?=$edit?'(เว้นว่างหากไม่เปลี่ยน)':''?></label><input type="password" name="password" <?=$edit?'':'required'?>></div><div class="field"><label>สิทธิ์</label><select name="role"><option value="editor" <?=($edit['role']??'')==='editor'?'selected':''?>>Editor</option><option value="admin" <?=($edit['role']??'admin')==='admin'?'selected':''?>>Admin</option></select></div><button class="btn">บันทึก</button></form></div><h2>รายการผู้ใช้</h2><div class="table-wrap"><table><thead><tr><th>ชื่อ</th><th>อีเมล</th><th>สิทธิ์</th><th>สถานะ</th><th>จัดการ</th></tr></thead><tbody><?php foreach($users as $user):?><tr><td><?=e($user['name'])?></td><td><?=e($user['email'])?></td><td><?=e($user['role'])?></td><td><?=$user['is_active']?'ใช้งาน':'ปิด'?></td><td><div class="actions"><a class="btn secondary" href="?edit=<?=(int)$user['id']?>">แก้ไข</a><?php if((int)$user['id']!==(int)$me['id']):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=(int)$user['id']?>"><button class="btn danger"><?=$user['is_active']?'ปิด':'เปิด'?></button></form><?php endif?></div></td></tr><?php endforeach?></tbody></table></div><?php page_footer();?>
